/* These aliases keep descriptive names while preserving verified BSS linker names. */

unsigned int current_file_name;
/* Bytes written by the most recent file operation. */
unsigned int file_output_bytes_written;
/* TU ignore_file_data..load_next_file [0x105a7, 0x108a9): generated by tools/tu.py */
#include <stdio.h>
/* Shared file-buffer state used by the picture loader and decoders. */
/* Number of bytes read by the most recent file operation. */
unsigned int n_read;
unsigned int current_file_size_bytes;
/* Cursor into the aligned file/image buffer. */
unsigned int file_buf_ptr;
int read_file_with_decoder(char *name, void *buf);
enum FileOperationError {
    FILE_ERROR_OPEN = 0x201,
    FILE_ERROR_READ = 0x203,
    FILE_ERROR_WRITE = 0x204,
    FILE_ERROR_SEEK = 0x205,
    FILE_ERROR_TELL = 0x206,
    FILE_ERROR_BUFFER_OVERFLOW = 0x207
};

int ignore_file_data(void);
unsigned int file_error_state = 0;
/* Upper address bound for writes into the shared file buffer. */
unsigned int buf_lim = 1000000000;
int (*decode_hook)() = ignore_file_data;
unsigned int file_load_nesting_state = 0xffffffff;
int ignore_file_data(void) {
    return 0;
}

int get_file_length(char * file_path) {
    FILE * file;
    int error_code;
    current_file_name=(unsigned int)file_path;
    file=fopen(file_path,"r+b");
    if(file==0) error_code=FILE_ERROR_OPEN;
    else {
        if(fseek(file,0,2)!=0) error_code=FILE_ERROR_SEEK;
        else {
            current_file_size_bytes=(unsigned int)ftell(file);
            if(current_file_size_bytes==0xffffffffU) error_code=FILE_ERROR_TELL;
            else error_code=0;
        }
        fclose(file);
    }
    return error_code;
}

/* The decoder return value is the unconsumed tail; the shared cursor advances past bytes read. */
int read_file_with_decoder(char * file_path,void * destination_buffer) {
    FILE * file;
    int error_code;
    int decode_status;
    unsigned int file_length;
    ++file_load_nesting_state;
    current_file_name=(unsigned int)file_path;
    file=fopen(file_path,"r+b");
    if(file==0) error_code=FILE_ERROR_OPEN;
    else {
        if(fseek(file,0,2)!=0) error_code=FILE_ERROR_SEEK;
        else {
            file_length=(unsigned int)ftell(file);
            if(file_length==0xffffffffU) error_code=FILE_ERROR_TELL;
            else {
                if(fseek(file,0,0)!=0) error_code=FILE_ERROR_SEEK;
                else {
                    if((unsigned int)destination_buffer+file_length>buf_lim && file_load_nesting_state!=0) error_code=FILE_ERROR_BUFFER_OVERFLOW;
                    else {
                        n_read=(unsigned int)fread(destination_buffer,1,file_length,file);
                        if(n_read!=file_length) error_code=FILE_ERROR_READ;
                        else {
                            decode_status=decode_hook(destination_buffer,n_read);
                            if(decode_status<0) {
                                 file_error_state=0;
                                file_buf_ptr=file_error_state;
                            }
                            else {
                                n_read-=decode_status;
                                error_code=0;
                            }
                        }
                    }
                }
            }
        }
        fclose(file);
    }
    file_load_nesting_state=0xffffffffU;
    return error_code;
}

int write_file_buffer(char * file_path,void * source_buffer,unsigned int byte_count) {
    FILE * file;
    int error_code;
    current_file_name=(unsigned int)file_path;
    file=fopen(file_path,"w+b");
    if(file==0) error_code=FILE_ERROR_OPEN;
    else {
        if(fseek(file,0,0)!=0) error_code=FILE_ERROR_SEEK;
        else {
            file_output_bytes_written=(unsigned int)fwrite(source_buffer,1,byte_count,file);
            if(file_output_bytes_written!=byte_count) error_code=FILE_ERROR_WRITE;
            else error_code=0;
        }
        fclose(file);
    }
    return error_code;
}

int load_next_file(char * file_path) {
    int read_status;
    --file_load_nesting_state;
    read_status=read_file_with_decoder(file_path,(void *)file_buf_ptr);
    file_buf_ptr+=n_read;
    file_buf_ptr=(file_buf_ptr+3)&0xfffffffcU;
    return read_status;
}
